#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;

long long qmi(long long a, long long b) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    vector<int> cnt(26, 0);
    for (char ch : s) {
        cnt[ch - 'a']++;
    }

    long long ans = 0;
    for (int i = 0; i < 26; ++i) {
        if (cnt[i] < 2) continue;
        // 当前字符 i 选择 2 个的方案数
        long long ways = 1LL * cnt[i] * (cnt[i] - 1) / 2;
        long long prod = 1;
        for (int j = 0; j < 26; ++j) {
            if (j == i) continue;
            // 总方案 2^cnt[j] 减去恰好出现2次的方案
            long long cur = (qmi(2, cnt[j]) - 1LL * cnt[j] * (cnt[j] - 1) / 2) % MOD;
            if (cur < 0) cur += MOD;
            prod = (prod * cur) % MOD;
        }
        ans = (ans + ways * prod) % MOD;
    }

    cout << ans << '\n';
    return 0;
}
